// Minimal-but-faithful mock of @minecraft/server 2.x for node tests (rebuilt 2026-09-27, v2.6.1: Player.spawnParticle · world.getEntity, v2.6.3: player.hunger · player.saturation · equippable.totalArmor).
// Test helpers: sim, emit, advance, vanillaHurt, FakeEntity, FakePlayer.
import { readdirSync, readFileSync, statSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

// v1.7.0: 빌드된 행동 팩 엔티티(RPG_BP/entities)에서 몬스터 등의 최대 체력·가족을 읽음 (테스트가 빌드 결과와 같게)
const ENTITY_DEFS = (() => {
  const out = {};
  const root = join(dirname(fileURLToPath(import.meta.url)), "..", "..", "..", "..", "..", "RPG_BP", "entities");
  const walk = (d) => {
    let names = [];
    try {
      names = readdirSync(d);
    } catch {
      return;
    }
    for (const n of names) {
      const p = join(d, n);
      if (statSync(p).isDirectory()) walk(p);
      else if (n.endsWith(".json")) {
        try {
          const e = JSON.parse(readFileSync(p, "utf-8"))["minecraft:entity"];
          const c = e?.components ?? {};
          out[e.description.identifier] = { max: c["minecraft:health"]?.max, families: c["minecraft:type_family"]?.family, box: c["minecraft:collision_box"], scale: c["minecraft:scale"]?.value, properties: e.description.properties, events: e.events ? Object.keys(e.events) : undefined, rideable: c["minecraft:rideable"] };
        } catch {
          // 무시
        }
      }
    }
  };
  walk(root);
  return out;
})();
export const entityDefs = ENTITY_DEFS;
// v1.8.0: 빌드된 사용자 블록 (RPG_BP/blocks): 이 밖의 rpg: 이름은 블록이 아님 (무기·룬 등 아이템)
const CUSTOM_BLOCKS = (() => {
  const out = new Set();
  const walk = (d) => {
    let names = [];
    try {
      names = readdirSync(d);
    } catch {
      return;
    }
    for (const n of names) {
      const p = join(d, n);
      if (statSync(p).isDirectory()) walk(p);
      else if (n.endsWith(".json")) {
        try {
          const b = JSON.parse(readFileSync(p, "utf-8"))["minecraft:block"];
          if (b?.description?.identifier) out.add(b.description.identifier);
        } catch {
          // 무시
        }
      }
    }
  };
  walk(join(dirname(fileURLToPath(import.meta.url)), "..", "..", "..", "..", "..", "RPG_BP", "blocks"));
  return out;
})();

// v2.6.3: 갑옷 방어 포인트 (equippable.totalArmor): 빌드된 행동 팩 갑옷 (minecraft:wearable protection) + 바닐라 갑옷
const ARMOR_POINTS = (() => {
  const out = {};
  const mats = { leather: [1, 3, 2, 1], chainmail: [2, 5, 4, 1], iron: [2, 6, 5, 2], golden: [2, 5, 3, 1], diamond: [3, 8, 6, 3], netherite: [3, 8, 6, 3] };
  for (const [m, v] of Object.entries(mats)) ["helmet", "chestplate", "leggings", "boots"].forEach((k, i) => (out[`minecraft:${m}_${k}`] = v[i]));
  out["minecraft:turtle_helmet"] = 2;
  const walk = (d) => {
    let names = [];
    try {
      names = readdirSync(d);
    } catch {
      return;
    }
    for (const n of names) {
      const p = join(d, n);
      if (statSync(p).isDirectory()) walk(p);
      else if (n.endsWith(".json")) {
        try {
          const it = JSON.parse(readFileSync(p, "utf-8"))["minecraft:item"];
          const w = it?.components?.["minecraft:wearable"];
          if (it?.description?.identifier && Number.isFinite(w?.protection)) out[it.description.identifier] = w.protection;
        } catch {
          // 무시
        }
      }
    }
  };
  walk(join(dirname(fileURLToPath(import.meta.url)), "..", "..", "..", "..", "..", "RPG_BP", "items"));
  return out;
})();
export const armorPointsTable = ARMOR_POINTS;

